/* ==========================================================
   4. TEXT NODE LIST (JAVÍTOTT - Platformfüggetlen)
========================================================== */
function getTextNodes(root) {
  // 1. Normalizálás: összeforrasztja a széttöredezett szövegeket
  root.normalize(); 

  const walker = document.createTreeWalker(
    root,
    NodeFilter.SHOW_TEXT,
    {
        acceptNode: function(node) {
            // FONTOS: Csak akkor fogadjuk el a node-ot, ha van benne
            // valódi karakter, nem csak szóköz/sortörés.
            // Így a telefon és a gép ugyanazt a listát látja majd.
            if (node.nodeValue.trim().length === 0) {
                return NodeFilter.FILTER_REJECT; // Ez "szemét", eldobjuk
            }
            return NodeFilter.FILTER_ACCEPT; // Ez hasznos szöveg
        }
    }
  );

  const nodes = [];
  while (walker.nextNode()) {
      nodes.push(walker.currentNode);
  }
  return nodes;
}

