ui.bookmarkBtn.onclick = () => {
  const user = auth.currentUser;
  if (!user) return;

  const sel = window.getSelection();
  if (!sel.rangeCount || !sel.toString().trim()) return;

  // 1. lépés: Takarítás, hogy a mentés a "nyers" állapot alapján történjen
  removeOldBookmark(); 

  const range = sel.getRangeAt(0);
  // Újra lekérjük a node-okat a normalizálás után
  const textNodes = getTextNodes(ui.bookContent);

  const startNodeIndex = textNodes.indexOf(range.startContainer);
  const endNodeIndex = textNodes.indexOf(range.endContainer);

  if (startNodeIndex === -1 || endNodeIndex === -1) {
      showToast("HIBA: Nem található a szövegrész!");
      return;
  }

  set(
    ref(db, `bookmarks/${user.uid}/${ui.bookSelector.value}`),
    {
      startNodeIndex,
      startOffset: range.startOffset,
      endNodeIndex,
      endOffset: range.endOffset
    }
  ).then(() => {
      showToast("Könyvjelző mentve!");
      // Opcionális: Visszarakhatjuk a jelölést vizuálisan, ha akarjuk, 
      // de egyszerűbb, ha a felhasználó látja, hogy mentve lett.
  });
};

