ui.gotoBookmarkBtn.onclick = () => {
  const user = auth.currentUser;
  if (!user) return;

  get(ref(db, `bookmarks/${user.uid}/${ui.bookSelector.value}`))
    .then(snap => {
      const d = snap.val();
      if (!d) return;
      restoreExact(d);
    });
};
/* ==========================================================
   7. RESTORE — JAVÍTOTT & BIZTONSÁGOS
========================================================== */
// Segédfüggvény a takarításhoz
function removeOldBookmark() {
    const old = document.getElementById("bookmark-marker");
    if (old) {
        // A tartalmát visszarakjuk szövegként
        const text = document.createTextNode(old.textContent);
        old.replaceWith(text);
    }
    // Összeolvasztjuk a szomszédos szöveg-csomópontokat
    ui.bookContent.normalize();
}

function restoreExact(d) {
  // 1. Régi marker törlése és DOM rendrakás
  removeOldBookmark();

  // 2. Node-ok lekérése a tiszta állapotból
  const textNodes = getTextNodes(ui.bookContent);

  const startNode = textNodes[d.startNodeIndex];
  const endNode = textNodes[d.endNodeIndex];

  // Biztonsági ellenőrzések (hogy ne fagyjon ki, ha mégis baj van)
  if (!startNode || !endNode) {
      console.error("Hiba: A node index nem található.");
      return;
  }

  // Ellenőrizzük, hogy az offset belefér-e a node hosszába
  if (d.startOffset > startNode.length || d.endOffset > endNode.length) {
      console.error("Hiba: A szöveg hossza megváltozott, az offset érvénytelen.");
      showToast("Hiba: A könyv tartalma változott.");
      return;
  }

  try {
      const range = document.createRange();
      range.setStart(startNode, d.startOffset);
      range.setEnd(endNode, d.endOffset);

      const span = document.createElement("span");
      span.id = "bookmark-marker";
      span.style.background = "#ffffff9d";
      span.style.color = "#000";

      span.appendChild(range.extractContents());
      range.insertNode(span);

      span.scrollIntoView({ behavior: "smooth", block: "center" });
  } catch (err) {
      console.error("DOM Hiba visszatöltéskor:", err);
  }
}
