/* ==========================================================
   11. IMMERZÍV MÓD (Gombok elrejtése/megjelenítése) - JAVÍTOTT
========================================================== */

let lastScrollTop = window.scrollY || document.documentElement.scrollTop;
const controlsDiv = document.getElementById("controls");

// Összegyűjtjük az összes lebegő gombot
// Frissített gombgyűjtő
function getUIButtons() {
    const btns = [];
    if (controlsDiv) {
        controlsDiv.querySelectorAll("button").forEach(btn => btns.push(btn));
    }
    // Biztosítjuk, hogy minden gomb benne legyen (bár most már mind a controlsban van)
    return btns;
}
function toggleUI(show) {
    const buttons = getUIButtons();
    buttons.forEach(btn => {
        if (show) {
            btn.classList.remove("ui-hidden");
        } else {
            btn.classList.add("ui-hidden");
        }
    });
}

// 1. GÖRGETÉS FIGYELÉSE
window.addEventListener("scroll", () => {
    const st = window.scrollY || document.documentElement.scrollTop;
    
    // Csak akkor rejtjük el, ha lefelé görgetünk, ÉS nem vagyunk az oldal legtetején
    if (st > lastScrollTop && st > 50) {
        toggleUI(false); // Eltűnés
    } else {
        toggleUI(true);  // Megjelenés
    }
    lastScrollTop = st <= 0 ? 0 : st;
}, { passive: true });

// 2. EGÉR MOZGÁS (Ha megmozdul az egér, jöjjenek elő a gombok)
window.addEventListener("mousemove", () => {
    toggleUI(true);
});

// 3. ÉRINTÉS (Mobilon, ha hozzáérsz a képernyőhöz, jelenjenek meg)
window.addEventListener("touchstart", () => {
    toggleUI(true);
}, { passive: true });

// 4. KIJELÖLÉS (Ha szöveget jelölsz, maradjanak láthatóak)
document.addEventListener("selectionchange", () => {
    const selection = document.getSelection();
    if (selection && selection.toString().length > 0) {
        toggleUI(true);
    }
});
/* ==========================================================
   12. TELJES KÉPERNYŐ (FULLSCREEN) KEZELÉS
========================================================== */
const fullscreenBtn = document.getElementById("fullscreen-btn");
const fullscreenIcon = fullscreenBtn ? fullscreenBtn.querySelector("i") : null;

if (fullscreenBtn) {
    fullscreenBtn.addEventListener("click", () => {
        if (!document.fullscreenElement) {
            // Belépés teljes képernyőbe
            document.documentElement.requestFullscreen().catch(err => {
                console.log(`Hiba a teljes képernyőnél: ${err.message}`);
            });
            // Ikon csere: összenyomásra
            if(fullscreenIcon) fullscreenIcon.className = "fa-solid fa-compress";
        } else {
            // Kilépés
            if (document.exitFullscreen) {
                document.exitFullscreen();
            }
            // Ikon csere: kiterjesztésre
            if(fullscreenIcon) fullscreenIcon.className = "fa-solid fa-expand";
        }
    });
}